{{-- Blog post card (blog/PostCard.tsx). $p Post, $wide --}}
@php($B = \App\Support\Site\Blog::class)
<article class="{{ !empty($wide) ? 'bl-card wide' : 'bl-card' }}"><a href="/blogs/{{ $p->slug }}" class="bl-card-img" tabindex="-1" aria-hidden="true"><img src="{{ $p->image ?: '/posts/default.webp' }}" alt="" loading="lazy" width="1200" height="675"></a><div class="bl-card-body"><div class="bl-tags">@if (!empty($wide))<span class="bl-tag star">Featured</span>@endif<span class="bl-tag">{{ $p->category ?: 'Insights' }}</span></div><h3><a href="/blogs/{{ $p->slug }}">{{ $p->title }}</a></h3>@if (!empty($wide))<p>{{ $p->excerpt }}</p>@endif<p class="bl-meta">GTech Editorial Team · {{ $B::date($p) }} · {{ $B::readTime((string) $p->body) }} min read</p>@if (!empty($wide))<a class="bl-read" href="/blogs/{{ $p->slug }}">Read Article</a>@endif</div></article>
